import { test } from 'node:test'
import assert from 'node:assert/strict'
import { existsSync, readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'

// Item sprite manifest (generated by tools/download-item-sprites.cjs). These
// modules are standalone data tables, so no game-data globals are needed.
const { activeItems, consumableItems, evolutionItems, heldItems, pokeBalls, coreMartItems, regionalMartItems, tokenShopItems, valuableDropTable } =
  await import('../src/data/items.js')
const { AUCTION_LOTS } = await import('../src/game/minigames/auction-house.js')

const root = join(dirname(fileURLToPath(import.meta.url)), '..'),
  manifest = JSON.parse(readFileSync(join(root, 'public', 'data', 'item-icons.json'), 'utf8'))

/** Every item id the bag / a shop / an auction lot can show (balls use PokeballIcon). */
function inventoryItemIds() {
  const ids = new Set(),
    addTable = (/** @type {Record<string, any>} */ table) => {
      for (const item of Object.values(table)) if (item?.id) ids.add(item.id)
    },
    addEntries = (/** @type {{ itemId: string }[]} */ entries) => {
      for (const entry of entries) if (entry?.itemId) ids.add(entry.itemId)
    }
  addTable(activeItems)
  addTable(consumableItems)
  addTable(heldItems)
  addTable(evolutionItems)
  addEntries(valuableDropTable)
  addEntries(coreMartItems)
  for (const stock of Object.values(regionalMartItems)) addEntries(stock)
  addEntries(tokenShopItems)
  for (const lot of AUCTION_LOTS) addEntries(lot.items)
  for (const ballId of Object.keys(pokeBalls)) ids.delete(ballId)
  return ids
}

test('every bag, shop and auction item has a downloaded sprite', () => {
  for (const itemId of inventoryItemIds()) {
    assert.ok(manifest[itemId], `${itemId} has no icon — re-run tools/download-item-sprites.cjs`)
    assert.ok(
      existsSync(join(root, 'public', 'sprites', 'items', manifest[itemId])),
      `${itemId} sprite file ${manifest[itemId]} is missing`
    )
  }
})
